package br.com.tapeteskalke.entity; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="usuario") @Getter @Setter public class Usuario extends BaseAuditEntity { @Column(nullable=false,length=150) private String nome; @Column(nullable=false,unique=true,length=180) private String email; @Column(name="senha_hash",nullable=false) private String senhaHash; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_cargo",nullable=false) private Cargo cargo; @Column(nullable=false) private boolean ativo=true; @Column(name="sessao_versao",nullable=false) private long sessaoVersao; }